import pytest
from pathlib import Path
from bs4 import BeautifulSoup

@pytest.fixture
def html_content():
    path = Path(__file__).parent / 'index.html'
    return path.read_text(encoding='utf-8')

@pytest.fixture
def soup(html_content):
    return BeautifulSoup(html_content, 'html.parser')


def test_form_and_required_fields(soup):
    form = soup.find('form', {'id': 'claim-form'})
    assert form is not None

    required_ids = ['policy-number', 'member-id', 'last-day-worked', 'first-day-absent', 'nature-of-absence']
    for rid in required_ids:
        element = form.find(id=rid)
        assert element is not None
        assert element.has_attr('aria-required')
        assert element['aria-required'] == 'true'

def test_upload_input_allows_multiple_files(soup):
    file_input = soup.find('input', {'type': 'file'})
    assert file_input is not None
    assert file_input.has_attr('multiple')

def test_confirmation_panel_and_status_markup(soup):
    confirmation_div = soup.find('div', {'id': 'confirmation'})
    assert confirmation_div is not None
    assert confirmation_div.get('aria-live') == 'polite'
    ref_number_span = confirmation_div.find('span', {'id': 'ref-number'})
    assert ref_number_span is not None

def test_member_lookup_mock_data_exists(soup):
    script = soup.find('script', string=lambda text: text and 'mockData' in text)
    assert script is not None
    assert '12345' in script.string
    assert 'John Doe' in script.string
    assert '67890' in script.string
    assert 'Jane Smith' in script.string

def test_generated_reference_number_exists(soup):
    script = soup.find('script')
    assert script is not None
    assert 'Math.floor(Math.random() * 9000 + 1000)' in script.string

def test_interactive_elements_have_aria_labels(soup):
    buttons = soup.find_all('button')
    for button in buttons:
        assert button.has_attr('aria-label') and len(button['aria-label'].strip()) > 0

def test_color_contrast_ratio(soup):
    style_tag = soup.find('style')
    assert style_tag is not None
    assert '#333' in style_tag.string
    assert '#ffffff' in style_tag.string and '#f9f9f9' not in style_tag.string


